<script setup lang="ts">import type{InvoiceFailure,InvoiceStatusItem}from '@/types/dashboard';defineProps<{statuses:InvoiceStatusItem[];failures:InvoiceFailure[];loading:boolean;publishing:boolean}>();const emit=defineEmits<{retry:[id:number]}>();const colors:Record<string,string>={CHO_PHAT_HANH:'warning',DANG_PHAT_HANH:'info',DA_PHAT_HANH:'success',PHAT_HANH_LOI:'error',DA_HUY:'default'};const money=(v:number)=>new Intl.NumberFormat('vi-VN',{notation:'compact',maximumFractionDigits:1}).format(v);function retry(id:number){if(window.confirm('Phát hành lại hóa đơn này?'))emit('retry',id)}</script>
<template><v-card class="pa-4 pa-md-5 h-100" border rounded="xl"><div class="text-h6 font-weight-bold">Trạng thái hóa đơn</div><div class="text-caption text-medium-emphasis mb-4">Số lượng và giá trị theo trạng thái</div><v-skeleton-loader v-if="loading" type="list-item-two-line@4"/><template v-else><div class="invoice-status-grid"><div v-for="item in statuses" :key="item.status" class="invoice-status-item"><v-icon icon="mdi-circle" :color="colors[item.status]" size="12"/><div><span>{{ item.label }}</span><strong>{{ item.count }}</strong><small>{{ money(item.amount) }} ₫</small></div></div></div><v-divider v-if="failures.length" class="my-4"/><div v-if="failures.length"><div class="font-weight-bold text-error mb-2">Hóa đơn cần phát hành lại</div><div v-for="item in failures.slice(0,4)" :key="item.invoice_id" class="invoice-failure"><div class="min-width-0"><div class="font-weight-medium text-truncate">{{ item.household_name }} · {{ item.payment_code }}</div><div class="text-caption text-error text-truncate">{{ item.error }}</div><div class="text-caption text-medium-emphasis">{{ money(item.amount) }} ₫ · Đã thử {{ item.retry_count }} lần</div></div><v-btn size="small" color="error" variant="tonal" :loading="publishing" @click="retry(item.payment_id)">Thử lại</v-btn></div></div></template></v-card></template>
